!function(){"use strict";window.addEventListener("load",()=>{!function(){const e=document.querySelector(".page"),t=document.querySelector(".hamburger-button");if(!t)return;const r=t.querySelector(".hamburger"),c=document.querySelector(".header__slider");t.addEventListener("click",()=>{e.classList.toggle("unscrollable"),r.classList.toggle("active"),c.classList.toggle("header__slider--active")})}()})}();
